import zipfile, re, xml.etree.ElementTree as ET, os
from pathlib import Path

base = Path('.')
files = {
    'pptx': base/'assets/ppt_pack/76bb19d2_开题报告-颜雍颀-V3.pptx',
    'docx': base/'assets/uploads/fde1237c_开题报告-颜雍颀(1).docx',
}

def extract_ppt_text(pptx_path):
    ns = {'a':'http://schemas.openxmlformats.org/drawingml/2006/main','p':'http://schemas.openxmlformats.org/presentationml/2006/main'}
    out=[]
    with zipfile.ZipFile(pptx_path) as z:
        slide_files=sorted([n for n in z.namelist() if n.startswith('ppt/slides/slide') and n.endswith('.xml')], key=lambda x:int(re.search(r'slide(\d+)\.xml', x).group(1)))
        for sf in slide_files:
            root=ET.fromstring(z.read(sf))
            texts=[t.text.strip() for t in root.findall('.//a:t', ns) if t.text and t.text.strip()]
            out.append((sf, texts))
    return out

def extract_docx_paras(docx_path):
    ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
    paras=[]
    with zipfile.ZipFile(docx_path) as z:
        root=ET.fromstring(z.read('word/document.xml'))
        for p in root.findall('.//w:p', ns):
            texts=[t.text for t in p.findall('.//w:t', ns) if t.text]
            if texts:
                txt=''.join(texts).strip()
                if txt:
                    paras.append(txt)
    return paras

ppt = extract_ppt_text(files['pptx'])
print('PPT slides:', len(ppt))
for sf,texts in ppt:
    preview=' | '.join(texts[:15])
    print('\n###', sf)
    print(preview[:1200])

paras = extract_docx_paras(files['docx'])
print('\nDOCX paras:', len(paras))
for i,p in enumerate(paras[:220]):
    print(f'{i+1:03d}: {p}')
